// Serve the approved Laurea Smart UI on the existing app domain.
// No CRM credentials, Connector changes, or native app changes.
const SITE = 'https://laureasmart.it';
const ASSETS = '/wp-content/plugins/laureasmart-collaudo/assets/';
const APP_ORIGIN = 'https://app.laureasmart.it';
const RELEASE_APP_JS="(()=>{\n'use strict';\nconst KEY='ls_budget_carriera_v1';\nconst blank=()=>({budget:{range:'',payment:'',topics:[],done:false},career:{paths:[],course:'',status:'',credits:'',exams:'',sector:'',role:'',years:'',skills:'',goal:'',done:false}});\nlet state=blank(),storageOK=true;\ntry{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.budget&&saved?.career)state=saved;}catch(e){storageOK=false;}\nconst main={addEventListener:(...a)=>document.addEventListener(...a),querySelectorAll:(...a)=>document.getElementById('main').querySelectorAll(...a)};\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}}\nconst ranges=['125–175 € al mese','176–225 € al mese','226–300 € al mese','Oltre 300 € al mese','Da capire con l’orientatore'];\nfunction option(name,value,label,type='radio',selected=false,desc=''){return `<label class=\"option\"><input type=\"${type}\" name=\"${name}\" value=\"${esc(value)}\" ${selected?'checked':''}><span>${esc(label)}${desc?`<small>${esc(desc)}</small>`:''}</span></label>`;}\nfunction choices(name,items,value,type='radio'){return `<div class=\"options\">${items.map(x=>option(name,x,x,type,type==='checkbox'?value.includes(x):value===x)).join('')}</div>`;}\nfunction field(name,label,value='',type='text',hint=''){return `<div class=\"field\"><label for=\"${name}\">${label}</label><input id=\"${name}\" name=\"${name}\" type=\"${type}\" value=\"${esc(value)}\" ${type==='number'?'min=\"0\" max=\"999\" inputmode=\"numeric\" step=\"1\"':''} maxlength=\"150\">${hint?`<div class=\"small\">${hint}</div>`:''}</div>`;}\nfunction area(name,label,value){return `<div class=\"field\"><label for=\"${name}\">${label}</label><textarea id=\"${name}\" name=\"${name}\" maxlength=\"600\">${esc(value)}</textarea></div>`;}\nfunction heading(k,title,desc){return `<div class=\"eyebrow\">${k}</div><h1>${title}</h1><p>${desc}</p>`;}\nfunction progress(n,total){return `<div class=\"step\">Passaggio ${n} di ${total} · puoi tornare indietro</div><div class=\"progress\">${Array.from({length:total},(_,i)=>`<i class=\"${i<n?'on':''}\"></i>`).join('')}</div>`;}\nfunction actions(next,back){return `<p id=\"error\" class=\"error\" role=\"alert\"></p><button class=\"primary\" type=\"submit\">${next}</button><a class=\"text\" href=\"#${back}\">← Indietro</a>`;}\nfunction form(id,body){return `<form id=\"${id}\" novalidate>${body}</form>`;}\nfunction fact(label,value){return `<div><dt>${esc(label)}</dt><dd>${esc(value||'Non indicato')}</dd></div>`;}\nfunction budgetFacts(){return `<dl class=\"facts\">${fact('Budget mensile indicativo',state.budget.range)}${fact('Pagamento preferito',state.budget.payment)}${fact('Da approfondire',state.budget.topics.join(', '))}</dl>`;}\nfunction careerFacts(){let c=state.career;return `<dl class=\"facts\">${fact('Il tuo punto di partenza',c.paths.join(' e '))}${c.paths.includes('Studi universitari')?fact('Corso e situazione',[c.course,c.status].filter(Boolean).join(' · '))+fact('Carriera dichiarata',[c.credits?`${c.credits} CFU`:'',c.exams?`${c.exams} esami`:''].filter(Boolean).join(' · ')):''}${c.paths.includes('Esperienza professionale')?fact('Lavoro',[c.role,c.sector,c.years].filter(Boolean).join(' · '))+fact('Attività e competenze',c.skills):''}${fact('Cosa vuoi ottenere',c.goal)}</dl>`;}\nfunction view(route){let b=state.budget,c=state.career,html='';\nif(route==='home')html=heading('Dopo il test','Diamo concretezza<br>al tuo prossimo passo.','Due strumenti per preparare la tua scelta. Completa solo ciò che conosci: potrai aggiornare tutto.')+`<a class=\"card card-link\" href=\"#budget\"><div class=\"icon\">€</div><div class=\"row\"><h2>Budget e agevolazioni</h2><span class=\"arrow\">→</span></div><p>Quanto vuoi dedicare agli studi ogni mese? Partiamo da 125 €.</p><span class=\"tag\">${b.done?'Completato':b.range?'Iniziato':'Da completare'}</span></a><a class=\"card card-link\" href=\"#career\"><div class=\"icon\">▤</div><div class=\"row\"><h2>Studi ed esperienza professionale</h2><span class=\"arrow\">→</span></div><p>Metti a fuoco gli studi già fatti e ciò che hai imparato lavorando.</p><span class=\"tag\">${c.done?'Completato':c.paths.length?'Iniziato':'Da completare'}</span></a><a class=\"secondary\" href=\"#consult\">Vedi il riepilogo per l’orientatore</a><div class=\"notice\">Prototipo locale. Non vengono inviati dati o richieste. Le fasce di budget non sono rette né offerte.</div><p class=\"small\">${storageOK?'Le risposte restano solo in questo browser.':'Il salvataggio non è disponibile: le risposte restano solo fino al ricaricamento.'} Non inserire documenti o informazioni riservate.</p><button class=\"text\" id=\"reset\">Azzera le risposte di prova</button>`;\nelse if(route==='budget')html=heading('Budget e agevolazioni','Un budget che parte da te.','Ragioniamo su una cifra mensile, senza impegni e senza scegliere ancora un ateneo.')+`<div class=\"card soft\"><div class=\"small\">IL PUNTO DI PARTENZA DELLA SIMULAZIONE</div><div class=\"money\">125 € <small>/ mese</small></div><p class=\"small\">È un riferimento per indicare il tuo budget, non un’offerta disponibile. Retta, rate e costi effettivi saranno verificati in consulenza.</p></div><a class=\"primary\" href=\"#budget-1\">${b.done?'Rivedi il budget':'Definisci il budget'} →</a>${b.done?'<a class=\"secondary\" href=\"#budget-summary\">Vedi il tuo riepilogo</a>':''}<a class=\"text\" href=\"#result\">← Il mio percorso</a>`;\nelse if(route==='budget-1')html=progress(1,3)+heading('Il tuo investimento','Quanto vorresti dedicare ogni mese?','Scegli una fascia sostenibile per te. Se non hai ancora un’idea, la definiamo insieme.')+form('b1',choices('range',ranges,b.range)+actions('Continua →','budget'));\nelse if(route==='budget-2')html=progress(2,3)+heading('Organizzazione dei pagamenti','Come preferiresti pagare?','Il budget resta espresso al mese. Qui indichi soltanto una preferenza, da verificare con l’orientatore.')+form('b2',choices('payment',['Preferisco rate mensili','Posso valutare un pagamento unico','Vorrei confrontare le possibilità'],b.payment)+actions('Continua →','budget-1'));\nelse if(route==='budget-3')html=progress(3,3)+heading('Le tue priorità','Cosa vuoi chiarire sui costi?','Puoi scegliere più aspetti, oppure proseguire senza selezionarne nessuno.')+form('b3',choices('topics',['Retta e cosa comprende','Possibilità di rateizzazione','Eventuali agevolazioni','Costi di esami, materiali e spostamenti'],b.topics,'checkbox')+`<div class=\"notice\">Non chiediamo ISEE, reddito o documenti. Un interesse per le agevolazioni non conferma il diritto a ottenerle.</div>`+actions('Salva il mio budget','budget-2'));\nelse if(route==='budget-summary')html=heading('Il tuo riepilogo','Il tuo quadro economico.','Una base concreta per parlare di sostenibilità del percorso.')+`<div class=\"card\">${budgetFacts()}</div><div class=\"notice\">Non è un preventivo. Importi, condizioni e agevolazioni dipendono dal percorso effettivo e devono essere verificati.</div><a class=\"primary\" href=\"#contact\">Parla con un orientatore →</a><p class=\"small\">Questo approfondimento resta su questo dispositivo: potrai discuterne durante la consulenza.</p><a class=\"secondary\" href=\"#career\">Aggiungi studi ed esperienza</a><a class=\"text\" href=\"#budget-1\">Modifica il budget</a>`;\nelse if(route==='career')html=heading('Studi ed esperienza','Partiamo da quello<br>che hai già fatto.','Studi ed esperienze di lavoro aiutano a capire quali possibilità approfondire.')+form('c0',`<fieldset><legend>Cosa vuoi aggiungere?</legend><p class=\"small\">Puoi selezionare entrambe le esperienze.</p>${choices('paths',['Studi universitari','Esperienza professionale'],c.paths,'checkbox')}${option('paths','Nessuna esperienza da aggiungere','Non ho ancora esperienze da aggiungere','checkbox',c.paths.includes('Nessuna esperienza da aggiungere'))}</fieldset>`+actions('Continua →','home'));\nelse if(route==='career-studies')html=heading('Studi universitari','La tua carriera di studio.','Inserisci ciò che ricordi. Non servono dati esatti o documenti in questa fase.')+form('cs',field('course','Corso frequentato · facoltativo',c.course)+`<fieldset><legend>Qual è la situazione attuale?</legend>${choices('status',['Studi interrotti','Studi in corso','Titolo conseguito','Da ricostruire'],c.status)}</fieldset><div class=\"split\">${field('credits','CFU conseguiti · facoltativo',c.credits,'number')}${field('exams','Esami sostenuti · facoltativo',c.exams,'number')}</div><p class=\"small\">Se non li ricordi, lascia i campi vuoti. Sono dati dichiarati, non CFU già riconosciuti.</p>`+actions('Continua →','career'));\nelse if(route==='career-work')html=heading('Esperienza professionale','Quello che sai fare conta.','Racconta il tipo di esperienza, senza indicare il datore di lavoro o informazioni riservate.')+form('cw',field('sector','Settore · facoltativo',c.sector)+field('role','Ruolo o tipo di lavoro · facoltativo',c.role)+`<fieldset><legend>Da quanto tempo lavori?</legend>${choices('years',['Meno di 2 anni','Da 2 a 5 anni','Da 6 a 10 anni','Oltre 10 anni','Preferisco approfondire a voce'],c.years)}</fieldset>`+area('skills','Attività e competenze · facoltativo',c.skills)+actions('Continua →',c.paths.includes('Studi universitari')?'career-studies':'career'));\nelse if(route==='career-goal')html=heading('Il tuo obiettivo','Dove vuoi arrivare?','Scegli la priorità di oggi. Potrai cambiarla quando vorrai.')+form('cg',choices('goal',['Riprendere e completare gli studi','Crescere nel mio settore','Cambiare settore professionale','Conseguire un titolo universitario','Capire quali possibilità ho'],c.goal)+`<div class=\"notice\">L’esperienza lavorativa aiuta l’orientamento. Non viene convertita automaticamente in crediti. L’eventuale riconoscimento degli studi precedenti è deciso dall’ateneo.</div>`+actions('Salva la mia storia',c.paths.includes('Esperienza professionale')?'career-work':c.paths.includes('Studi universitari')?'career-studies':'career'));\nelse if(route==='career-summary')html=heading('Il tuo riepilogo','La tua base di partenza.','Abbiamo raccolto gli elementi utili per approfondire il tuo percorso.')+`<div class=\"card\">${careerFacts()}</div><div class=\"notice\">Nessun riconoscimento di CFU è stato calcolato. Non hai inviato documenti o richieste.</div><a class=\"primary\" href=\"#contact\">Parla con un orientatore →</a><p class=\"small\">Questo approfondimento resta su questo dispositivo: potrai discuterne durante la consulenza.</p><a class=\"secondary\" href=\"#budget\">Completa il quadro economico</a><a class=\"text\" href=\"#career\">Modifica la tua storia</a>`;\nelse if(route==='consult')html=heading('Il prossimo passo','Un confronto già preparato.','Ecco gli elementi che potresti condividere con un orientatore. In questa anteprima non parte alcuna richiesta.')+`<div class=\"card\"><div class=\"linkrow\"><h2>Budget mensile</h2><a class=\"text\" href=\"#budget\">${b.done?'Modifica':'Completa'}</a></div>${b.done?budgetFacts():'<p>Non ancora completato.</p>'}</div><div class=\"card\"><div class=\"linkrow\"><h2>Studi e lavoro</h2><a class=\"text\" href=\"#career\">${c.done?'Modifica':'Completa'}</a></div>${c.done?careerFacts():'<p>Non ancora completato.</p>'}</div><button class=\"primary\" id=\"simulate\">Simula la richiesta di confronto</button><p class=\"small footer-note\">Solo dimostrazione: nessun recapito richiesto, nessun messaggio e nessun salvataggio nel CRM.</p><a class=\"text\" href=\"#result\">← Il mio percorso</a>`;\nelse if(route==='confirmation')html=heading('Prova completata','Il percorso è pronto.','Nella versione reale, questo riepilogo potrebbe accompagnare la richiesta di consulenza.')+`<div class=\"card soft\"><h2>Nessuna richiesta inviata.</h2><p>Hai provato il percorso locale. Le tue risposte restano disponibili in questo browser e puoi modificarle.</p></div><a class=\"primary\" href=\"#result\">Torna al mio spazio</a><a class=\"secondary\" href=\"#consult\">Rivedi il riepilogo</a>`;\nelse{return '';}\nreturn `<div class=\"ls-tools\">${html}</div>`;\n}\nfunction val(f,n){return new FormData(f).get(n)?.toString().trim()||'';}function all(f,n){return new FormData(f).getAll(n).map(String);}\nfunction go(route){save();location.hash=route;}\nmain.addEventListener('submit',e=>{const f=e.target;if(!['b1','b2','b3','c0','cs','cw','cg'].includes(f.id))return;e.preventDefault();let err='',next='';if(f.id==='b1'){let v=val(f,'range');if(!v)err='Scegli una fascia oppure “Da capire con l’orientatore”.';else{state.budget.range=v;state.budget.done=false;next='budget-2';}}\nif(f.id==='b2'){let v=val(f,'payment');if(!v)err='Indica una preferenza per continuare.';else{state.budget.payment=v;next='budget-3';}}\nif(f.id==='b3'){state.budget.topics=all(f,'topics');state.budget.done=true;next='budget-summary';}\nif(f.id==='c0'){let v=all(f,'paths');if(!v.length)err='Scegli un’esperienza oppure “Non ho ancora esperienze da aggiungere”.';else{state.career.paths=v;state.career.done=false;if(!v.includes('Studi universitari'))Object.assign(state.career,{course:'',status:'',credits:'',exams:''});if(!v.includes('Esperienza professionale'))Object.assign(state.career,{sector:'',role:'',years:'',skills:''});next=v.includes('Studi universitari')?'career-studies':v.includes('Esperienza professionale')?'career-work':'career-goal';}}\nif(f.id==='cs'){let status=val(f,'status');if(!status)err='Indica la situazione oppure “Da ricostruire”.';else if(!f.checkValidity())err='Inserisci un numero intero tra 0 e 999 per esami e CFU.';else{for(let k of ['course','status','credits','exams'])state.career[k]=val(f,k);next=state.career.paths.includes('Esperienza professionale')?'career-work':'career-goal';}}\nif(f.id==='cw'){if(!val(f,'years'))err='Indica una fascia oppure scegli di approfondire a voce.';else{for(let k of ['sector','role','years','skills'])state.career[k]=val(f,k);next='career-goal';}}\nif(f.id==='cg'){if(!val(f,'goal'))err='Scegli il tuo obiettivo attuale.';else{state.career.goal=val(f,'goal');state.career.done=true;next='career-summary';}}\nif(err){document.querySelector('#error').textContent=err;document.querySelector('#error').scrollIntoView({block:'center'});}else go(next);});\nmain.addEventListener('change',e=>{if(e.target.name==='paths'){let inputs=[...main.querySelectorAll('input[name=\"paths\"]')];if(e.target.value==='Nessuna esperienza da aggiungere'&&e.target.checked)inputs.filter(x=>x!==e.target).forEach(x=>x.checked=false);else if(e.target.checked)inputs.find(x=>x.value==='Nessuna esperienza da aggiungere').checked=false;}});\nwindow.LaureaTools={view,cards,summary,clear:()=>{state=blank();save();}};\n\nfunction cards(){return `<section class=\"ls-tools-entry\"><div class=\"section-heading\"><h2>Rendi concreta la tua scelta</h2><span>Due approfondimenti facoltativi</span></div><div class=\"workspace-grid\"><button class=\"workspace-link\" data-go=\"budget\"><span class=\"line-icon\" aria-hidden=\"true\">€</span><span><strong>Budget e agevolazioni</strong><small>Il tuo budget mensile, a partire da 125 € · ${state.budget.done?'Completato':state.budget.range?'Iniziato':'Da completare'}</small></span><span aria-hidden=\"true\">→</span></button><button class=\"workspace-link\" data-go=\"career\"><span class=\"line-icon\" aria-hidden=\"true\">▤</span><span><strong>Studi ed esperienza professionale</strong><small>Valorizza il tuo punto di partenza · ${state.career.done?'Completato':state.career.paths.length?'Iniziato':'Da completare'}</small></span><span aria-hidden=\"true\">→</span></button></div><p class=\"small\">Risposte salvate solo su questo dispositivo. Nessun preventivo o riconoscimento automatico di CFU.</p></section>`;}\nfunction summary(){if(!state.budget.done&&!state.career.done)return '';return `<section class=\"ls-tools\"><details class=\"card\"><summary>Budget, studi ed esperienza che hai approfondito</summary>${state.budget.done?budgetFacts():''}${state.career.done?careerFacts():''}<p class=\"small\">Questi dettagli restano sul dispositivo e non sono allegati automaticamente alla richiesta. Potrai discuterne con l’orientatore.</p><a class=\"text\" href=\"#budget\">Rivedi il budget</a> · <a class=\"text\" href=\"#career\">Rivedi studi e lavoro</a></details></section>`;}\n})();\n\n'use strict';\nconst lsNativeIOS=window.Capacitor?.getPlatform?.()==='ios'||window.Capacitor?.platform==='ios'||(/iPhone|iPad|iPod/.test(navigator.userAgent)&&!!window.webkit?.messageHandlers?.bridge);\nif(lsNativeIOS)document.documentElement.classList.add('native-ios');\nconst icons={cap:'<path d=\"M6 4v15h14\"/><path d=\"m9 14 11-10M13 4h7v7\"/>',home:'<path d=\"m3 10 9-7 9 7v10H3V10Z\"/><path d=\"M9 20v-7h6v7\"/>',route:'<circle cx=\"6\" cy=\"5\" r=\"2\"/><circle cx=\"18\" cy=\"19\" r=\"2\"/><path d=\"M6 7v7a4 4 0 0 0 4 4h6M10 5h4a4 4 0 0 1 0 8h-4\"/>',compass:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"m16 8-2 6-6 2 2-6 6-2Z\"/>',chat:'<path d=\"M21 11a8 8 0 0 1-8 8H8l-5 3V11a9 9 0 0 1 18 0Z\"/><path d=\"M8 10h8M8 14h5\"/>',arrow:'<path d=\"M4 12h15m-6-6 6 6-6 6\"/>',back:'<path d=\"M20 12H5m6-6-6 6 6 6\"/>',check:'<path d=\"m5 12 4 4L19 6\"/>',shield:'<path d=\"m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z\"/><path d=\"m8 12 3 3 5-6\"/>',book:'<path d=\"M12 5v16M3 3l9 2 9-2v16l-9 2-9-2V3Z\"/>',clock:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/>',building:'<path d=\"m3 8 9-5 9 5H3Zm2 3v7m5-7v7m4-7v7m5-7v7M3 21h18\"/>',mail:'<rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"m3 6 9 7 9-7\"/>',phone:'<path d=\"m4 3 4 1 1 5-3 2c2 3 4 5 7 7l2-3 5 1 1 4c-8 4-21-9-17-17Z\"/>',edit:'<path d=\"m15 4 5 5-11 11H4v-5L15 4Z\"/>',refresh:'<path d=\"M20 8a8 8 0 1 0 0 8M20 3v5h-5\"/>'};\nconst icon=n=>`<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">${icons[n]||icons.cap}</svg>`;\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst Q=LaureaQualification;\nconst isLive=()=>window.LaureaWPCRM?.mode==='wordpress-live';\nconst isTest=()=>!!window.LaureaWPCRM?.test;\nconst STORAGE=isLive()?'ls-live-qualification-v1':'ls-prototype-qualification-v2';\nfunction questions(){return Q.questions(answers);}\nconst schools=[{id:'flessibile',name:'Organizzazione flessibile',desc:'Per chi cerca uno studio da organizzare attorno ai propri impegni.',mode:'Materiali asincroni e organizzazione autonoma',support:'Tutor su appuntamento',exams:'Sede e calendario da verificare',cost:'Retta, tasse e servizi da confermare',fit:'Organizzazione del tempo'}, {id:'guidato',name:'Supporto allo studio',desc:'Per chi preferisce un accompagnamento frequente durante lo studio.',mode:'Materiali online e momenti di confronto',support:'Affiancamento periodico',exams:'Sede e modalità da verificare',cost:'Preventivo completo da richiedere',fit:'Supporto nello studio'}, {id:'territorio',name:'Esigenze logistiche',desc:'Per chi considera centrale la logistica delle attività in presenza.',mode:'Studio online con attenzione alla sede',support:'Punto di riferimento territoriale',exams:'Verifica della sede più comoda',cost:'Retta e costi di spostamento da valutare',fit:'Logistica degli esami'}];\nlet answers={};try{answers=Q.sanitize(JSON.parse(localStorage.getItem(STORAGE)||'{}'));}catch{answers={};}\nlet current=Math.max(0,questions().findIndex(q=>!answers[q.id])),selectedSchool='',selectedRoute='',channel='WhatsApp',submitted=false,screen='home';\nconst draft={email:'',name:'',surname:'',contact:'',permission:false,day:'',date:'',slot:''};\nlet confirmation=null,submitting=false;\nfunction romeToday(){const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-');}\nfunction contactWhen(){return draft.day==='date'?new Intl.DateTimeFormat('it-IT',{dateStyle:'long',timeZone:'Europe/Rome'}).format(new Date(draft.date+'T12:00:00+01:00')):draft.day==='first'?'Primo giorno utile':'Nessuna preferenza sul giorno';}\nfunction maskedContact(value){if(channel==='Email'){const [local,domain]=value.split('@');return local.slice(0,1)+'•••@'+domain;}return '••• '+value.replace(/\\D/g,'').slice(-4);}\nfunction save(){try{localStorage.setItem(STORAGE,JSON.stringify(answers));}catch{}}\nfunction recommended(){return Q.profile(answers).school;}\nfunction picked(){return schools.find(x=>x.id===selectedSchool)||schools.find(x=>x.id===recommended())||schools[0];}\nfunction areaName(){return answers.area&&answers.area!=='Non ho ancora un’area precisa'?answers.area:'Area da definire insieme';}\nfunction complete(){return Q.isComplete(answers);}\nfunction qualificationSummary(){const p=Q.profile(answers);return `<details class=\"verification qualification-summary\"><summary>${icon('book')}Riepilogo per l’orientatore</summary><p>Riepilogo delle esigenze da approfondire con il consulente. Tempi e desiderio di assistenza non determinano l’ammissione al percorso.</p><dl class=\"facts\"><div><dt>Percorso da valutare</dt><dd>${p.pathway}</dd></div><div><dt>Stato del confronto</dt><dd>${p.status}</dd></div><div><dt>Tempi dichiarati</dt><dd>${p.timing}</dd></div><div><dt>Aiuto desiderato</dt><dd>${p.next}</dd></div><div><dt>Ricontatto</dt><dd>${submitted?(isTest()?'Richiesta di prova':'Consulenza richiesta'):'Non richiesto: la preferenza nel test non è un’autorizzazione'}</dd></div>${questions().map(q=>`<div><dt>${q.title}</dt><dd>${esc(answers[q.id]||'Da completare')}</dd></div>`).join('')}</dl></details>`;}\nfunction go(s){location.hash=s;if(screen===s)render();}\nfunction primary(label,action){return `<button class=\"primary\" ${action}>${label}${icon('arrow')}</button>`;}\nfunction home(){const total=questions().length,count=questions().filter(q=>answers[q.id]).length;return `<header class=\"page-heading\"><span class=\"eyebrow\">La tua area personale</span><h1>${complete()?'Ripartiamo da te.':'Benvenuto in Laurea Smart.'}</h1><p>${complete()?'Rivedi il tuo orientamento o confronta le opzioni disponibili.':'Qui puoi orientarti, confrontare i percorsi e scegliere il prossimo passo.'}</p></header><section class=\"next-step\"><div class=\"step-icon\">${icon(complete()?'check':'compass')}</div><div class=\"next-copy\"><span class=\"eyebrow\">${complete()?'Orientamento completato':'Da dove iniziare'}</span><h2>${complete()?areaName():count?'Riprendi il tuo orientamento':'Costruisci il tuo orientamento'}</h2><p>${complete()?(quizAccessRequired()?'Le risposte sono pronte. Completa il profilo per accedere al risultato.':'Il tuo profilo è pronto. Esplora i criteri di scelta e le opzioni da approfondire.'):'Domande su requisiti, obiettivi e organizzazione. Alla fine, email, nome e cognome per vedere il risultato; telefono facoltativo. Puoi interrompere e riprendere.'}</p><div class=\"home-progress\"><div class=\"progress-line\" role=\"progressbar\" aria-label=\"Risposte completate\" aria-valuenow=\"${count}\" aria-valuemin=\"0\" aria-valuemax=\"${total}\"><div style=\"width:${count/total*100}%\"></div></div><span>${count} di ${total} risposte</span></div>${primary(complete()?(quizAccessRequired()?'Completa il profilo':'Apri il tuo risultato'):count?'Continua':'Inizia l’orientamento','data-action=\"start\"')}</div></section>${complete()&&!quizAccessRequired()?window.LaureaTools.cards():''}<div class=\"section-heading\"><h2>Il tuo spazio</h2><span>Esplora al tuo ritmo</span></div><div class=\"workspace-grid\"><button class=\"workspace-link\" data-go=\"compare\"><span class=\"line-icon\">${icon('building')}</span><span><strong>Le tue esigenze</strong><small>Organizzazione, supporto e sedi d’esame</small></span>${icon('arrow')}</button><button class=\"workspace-link\" data-go=\"contact\"><span class=\"line-icon\">${icon('chat')}</span><span><strong>Parla con un orientatore</strong><small>Un aiuto per chiarire dubbi e requisiti</small></span>${icon('arrow')}</button></div><section class=\"home-summary\"><div class=\"section-heading\"><h2>${count?'Le tue risposte':'Come funziona'}</h2>${count?'<button class=\"text-btn\" data-action=\"edit\">Modifica</button>':''}</div>${count?`<dl class=\"facts\"><div><dt>Obiettivo</dt><dd>${esc(answers.goal||'Da definire')}</dd></div><div><dt>Area di interesse</dt><dd>${esc(answers.area||'Da definire')}</dd></div><div><dt>Quando iniziare</dt><dd>${esc(answers.start||'Da definire')}</dd></div></dl>`:'<ol class=\"process-list\"><li><span>01</span><div><strong>Racconta le tue esigenze</strong><p>Rispondi al test e completa il profilo per vedere il risultato.</p></div></li><li><span>02</span><div><strong>Valuta le opzioni</strong><p>Scopri cosa confrontare e cosa verificare.</p></div></li><li><span>03</span><div><strong>Scegli come proseguire</strong><p>Richiedi assistenza soltanto se lo desideri.</p></div></li></ol>'}</section><div class=\"local-note\">${icon('shield')}Le risposte restano su questo browser fino al passaggio finale: con il salvataggio dell’email vengono inviate al CRM Laurea Smart.${count?'<button class=\"text-btn\" data-action=\"reset\">Azzera risposte</button>':''}</div>`;}\nfunction quiz(){const list=questions(),q=list[current];return `<header class=\"flow-heading\"><button class=\"icon-button\" data-action=\"previous\" aria-label=\"Indietro\">${icon('back')}</button><div><h1>Orientamento</h1><p>${['Obiettivo e requisiti','Interessi e organizzazione','Logistica e prossimo passo'][q.phase]}</p></div><span class=\"step-counter\">${current+1} / ${list.length}</span></header><div class=\"quiz-layout\"><aside class=\"quiz-aside\"><h2>Il tuo profilo</h2>${['Requisiti','Organizzazione','Preferenze'].map((p,i)=>`<div class=\"phase ${q.phase===i?'current':''}\"><b>${q.phase>i?'✓':i+1}</b>${p}</div>`).join('')}<p class=\"small\">Puoi modificare ogni risposta prima e dopo il risultato.</p></aside><section class=\"quiz-panel\" aria-labelledby=\"question\"><div class=\"step-meta\"><span>Domanda ${current+1} di ${list.length}</span><span>Una risposta</span></div><div class=\"progress-line\" role=\"progressbar\" aria-label=\"Avanzamento orientamento\" aria-valuemin=\"0\" aria-valuemax=\"${list.length}\" aria-valuenow=\"${current+1}\"><div style=\"width:${(current+1)/list.length*100}%\"></div></div><h2 id=\"question\">${q.title}</h2><p class=\"question-hint\">${q.hint}</p>${list.length>12&&current<5?'<p class=\"branch-note\">Le domande sugli studi precedenti compaiono solo quando pertinenti.</p>':''}<div class=\"options\" role=\"group\" aria-label=\"Scegli una risposta\">${q.type==='select'?`<label class=\"field\" for=\"region-answer\">Regione di riferimento<select id=\"region-answer\" class=\"quiz-select\"><option value=\"\">Seleziona una regione</option>${q.options.map((o,i)=>`<option value=\"${i}\" ${answers[q.id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`:q.options.map((o,i)=>`<button class=\"option\" data-answer=\"${i}\" aria-pressed=\"${answers[q.id]===o}\"><span class=\"radio\" aria-hidden=\"true\"></span>${o}</button>`).join('')}</div><div class=\"quiz-bottom\"><span class=\"small\">Risposte salvate su questo browser.</span><button class=\"primary\" data-action=\"next\" ${!answers[q.id]?'disabled':''}>${current===list.length-1?(quizAccessEnabled()?'Completa il tuo profilo':'Vedi il risultato'):'Continua'}${icon('arrow')}</button></div></section></div>`;}\nfunction result(){if(!complete())return empty('Il tuo percorso','Completa il test per vedere ambiti e criteri motivati dalle tue risposte.');const p=Q.profile(answers),d=Q.proposal(answers),c=d.consultation;return `<header class=\"page-heading heading-with-action\"><div><span class=\"eyebrow\">Il tuo risultato</span><h1>Le proposte da cui partire</h1><p>Percorsi da confrontare e criteri per scegliere l’ateneo.</p></div><button class=\"text-btn\" data-action=\"edit\">${icon('edit')}Modifica risposte</button></header><div class=\"notice\">${icon('shield')}<span>Gli ambiti indicati sono orientativi. Il consulente verificherà corsi disponibili, ateneo e requisiti prima di formulare una proposta.</span></div>${window.LaureaTools.cards()}<details class=\"snapshot-details\"><summary>Le risposte usate per queste proposte</summary><section class=\"result-snapshot\"><span><strong>Obiettivo</strong>${esc(answers.goal)}</span><span><strong>Area</strong>${areaName()}</span><span><strong>Esigenza</strong>${esc(answers.support)}</span></section></details>${d.blocked?`<section class=\"qualification-alert\"><h2>Prima di proporre corsi e atenei</h2><ul>${p.blocked.map(x=>`<li>${x}</li>`).join('')}</ul><p>Le preferenze sono state raccolte, ma non forziamo un abbinamento finché questi punti restano da chiarire.</p></section>`:''}<div class=\"result-layout proposal-layout\"><div><section aria-labelledby=\"routes-title\"><div class=\"section-heading\"><h2 id=\"routes-title\">${d.routes.length?'Quali percorsi approfondiremmo':'La direzione da chiarire'}</h2>${d.routes.length?'<span>2 ipotesi illustrative</span>':''}</div>${d.routes.length?d.routes.map((r,i)=>`${i?`<details class=\"route-alternative\" ${selectedRoute===r.id?'open':''}><summary>Altra direzione: ${r.title}</summary>`:''}<article class=\"route-proposal ${i===0?'route-proposal-main':''}\"><span class=\"badge\">${r.label}</span><span class=\"route-mode\">${r.mode}</span><h3>${r.title}</h3><p>${r.description}</p><p class=\"compact-reason\">${icon('check')}Dall’interesse che hai indicato: ${esc(answers.area)}.</p><details class=\"reason-block\"><summary>Perché lo valuteremmo e cosa verificare</summary>${r.why.map(w=>`<div class=\"answer-reason\"><span>Hai indicato: «${esc(w.answer)}»</span><p>${w.meaning}</p></div>`).join('')}<p class=\"proposal-verify\"><strong>Da verificare</strong> ${r.verify}</p></details><button class=\"secondary full ${selectedRoute===r.id?'is-selected':''}\" aria-pressed=\"${selectedRoute===r.id}\" data-route=\"${r.id}\">${icon(selectedRoute===r.id?'check':'book')}${selectedRoute===r.id?'Percorso selezionato':'Scegli questo percorso'}</button></article>${i?'</details>':''}` ).join(''):`<section class=\"card\"><h3>${d.blocked?'Prima i requisiti, poi il corso':'Nessuna proposta forzata'}</h3><p class=\"profile-note\">${d.blocked?'Il titolo dichiarato richiede una verifica prima di formulare una proposta specifica.':`Hai indicato «${esc(answers.goal)}» e «${esc(answers.area)}». Chiariremo prima il tipo di percorso e i contenuti che ti interessano.`}</p></section>`}</section><section class=\"card\"><h2>L’ateneo lo individuiamo insieme</h2><p>Il consulente valuterà le tue risposte e ti proporrà l’ateneo più adatto tra le opzioni effettivamente disponibili.</p><p class=\"small\">Supporto, organizzazione dello studio e sedi d’esame sono criteri da approfondire durante il confronto.</p><button class=\"text-btn\" data-go=\"compare\">Rivedi le tue esigenze</button></section><details class=\"verification\"><summary>${icon('shield')}Vincoli e verifiche ancora aperte</summary><dl class=\"facts\">${[['Budget annuale','budget'],['Regione di riferimento','region'],['Disponibilità per gli esami','travel'],['Tempo per lo studio','time'],['Quando iniziare','start']].map(([label,key])=>`<div><dt>${label}</dt><dd>${esc(answers[key])}</dd></div>`).join('')}</dl><ul>${p.checks.map(x=>`<li>${x}</li>`).join('')}<li>Verificare se ciascun ateneo offre il percorso individuato e se ne rispetta requisiti, costi e organizzazione.</li></ul></details>${qualificationSummary()}</div><aside class=\"next-panel consultation-panel\"><span class=\"eyebrow\">Il confronto, su misura per te</span><h2>${c.title}</h2><p>${c.text}</p><details class=\"consultation-topics\"><summary>Cosa chiariremmo insieme</summary><ul>${c.topics.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>${primary(c.button,'data-go=\"contact\"')}<p class=\"consultation-pace\">${c.pace}</p>${c.autonomous?'<button class=\"text-btn\" data-go=\"compare\">Continua in autonomia →</button>':''}<p class=\"footer-note\">${isLive()?'Il profilo e le risposte sono già salvati per l’orientamento. Puoi richiedere una consulenza indicando le tue preferenze di ricontatto.':'Richiesta simulata. Nessun contatto viene trasmesso.'}</p></aside></div><div class=\"journey-next\"><div><strong>${selectedRoute||selectedSchool?'Le tue scelte':'Puoi scegliere anche con l’orientatore'}</strong><span>${[d.routes.find(r=>r.id===selectedRoute)?.title,selectedSchool?picked().name:''].filter(Boolean).join(' · ')||'Nessuna scelta obbligatoria per chiedere aiuto.'}</span></div>${primary('Continua alla consulenza','data-go=\"contact\"')}</div>`;}\nfunction empty(title,text){return `<section class=\"card success\"><span class=\"success-icon\">${icon('compass')}</span><h1>${title}</h1><p>${text}</p>${primary('Inizia l’orientamento','data-action=\"start\"')}</section>`;}\nfunction compare(){return `<header class=\"page-heading\"><span class=\"eyebrow\">Le tue esigenze</span><h1>Cosa conta nella tua scelta</h1><p>Questi criteri aiutano il consulente a individuare l’ateneo e il percorso da proporti.</p></header><section class=\"card\"><h2>Il punto di partenza</h2><dl class=\"facts\">${[['Organizzazione dello studio',answers.work||'Da approfondire insieme'],['Tempo disponibile',answers.time||'Da approfondire insieme'],['Supporto desiderato',answers.support||'Da approfondire insieme'],['Regione di riferimento',answers.region||'Da approfondire insieme'],['Spostamenti',answers.travel||'Da approfondire insieme'],['Budget indicativo',answers.budget||'Da approfondire insieme']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class=\"small\">Sedi, modalità degli esami, requisiti e costi saranno verificati sul percorso effettivamente proposto. Nessun ateneo è selezionato automaticamente.</p><div class=\"actions\">${primary('Parla con un consulente','data-go=\"contact\"')}<button class=\"text-btn\" data-action=\"edit\">Rivedi le risposte</button></div></section>`;}\nfunction contact(){const proposal=Q.proposal(answers),chosenRoute=proposal.routes.find(r=>r.id===selectedRoute);if(submitted&&confirmation)return `<section class=\"card success\"><span class=\"success-icon\">${icon('check')}</span><div class=\"eyebrow\">${isLive()&&!isTest()?'Richiesta ricevuta':'Richiesta simulata'}</div><h1>Hai definito il prossimo passo</h1><p>${isLive()&&!isTest()?'Abbiamo ricevuto la tua richiesta di consulenza con le preferenze indicate.':confirmation.crm?.remote?'Il contatto sintetico è stato registrato nel CRM Laurea Smart. Nessuna comunicazione è stata inviata.':confirmation.crm?'Collaudo del collegamento locale riuscito. Nessun contatto è stato inviato al CRM online.':'Nessun contatto è stato inviato. Ecco le scelte della tua richiesta di prova.'}</p>${confirmation.crm?`<div class=\"notice\"><span>${isLive()?'Laurea Smart · Ricevuta':confirmation.crm.remote?'LeadPoint · Lead #'+confirmation.crm.leadId:'CRM simulato · Ricevuta locale'}<br>Riferimento: ${confirmation.crm.requestId}</span></div>`:''}<dl class=\"facts\"><div><dt>Percorso</dt><dd>${confirmation.route}</dd></div><div><dt>Ateneo</dt><dd>${confirmation.school}</dd></div><div><dt>Canale</dt><dd>${confirmation.channel}</dd></div><div><dt>${isLive()&&!isTest()?'Recapito':'Recapito di prova'}</dt><dd>${esc(confirmation.contact)}</dd></div><div><dt>Giorno preferito</dt><dd>${confirmation.day}</dd></div>${confirmation.channel!=='Email'?`<div><dt>Fascia oraria</dt><dd>${confirmation.slot}</dd></div>`:''}</dl><div class=\"notice confirmation-note\">${icon('clock')}<span>È una preferenza di ricontatto, non un appuntamento confermato.${confirmation.channel!=='Email'?' Orari riferiti al fuso Europe/Rome.':''}</span></div><div class=\"actions\">${primary('Torna al tuo percorso','data-go=\"result\"')}<button class=\"text-btn\" data-action=\"new-request\">Modifica la richiesta</button></div><p class=\"footer-note\">Il recapito completo è stato rimosso dalla memoria del modulo. Per modificare la richiesta dovrai reinserirlo. ${isLive()?'La richiesta è registrata nel CRM Laurea Smart.':window.LaureaWPCRM?'La richiesta di collaudo è salvata sul sito e nel CRM.':'Nessun dato del modulo è salvato in modo persistente.'}</p></section>`;return `<header class=\"page-heading\"><span class=\"eyebrow\">Orientatore</span><h1>Organizza il tuo confronto</h1><p>Scegli come e quando preferiresti essere ricontattato, partendo dalle opzioni che hai valutato.</p></header>${!isLive()&&window.LaureaCRM?.mode!=='prototype'?`<div class=\"notice\"><span><strong>${window.LaureaCRM?.mode?.endsWith('fixture')?'Collaudo LeadPoint online: solo Email laureasmart.prova-mappatura@example.test':'Collaudo CRM locale: nessun invio a leadpoint.it'}</strong></span></div>`:''}${isLive()&&isTest()?'<div class=\"notice\">Prova tecnica: usa laureasmart.prova-pubblico-20261101@example.test. Nessuna comunicazione automatica.</div>':''}${window.LaureaTools.summary()}<div class=\"contact-layout\"><section class=\"request-summary\"><h2>Di cosa parleremo</h2><dl class=\"facts\"><div><dt>Percorso scelto</dt><dd>${chosenRoute?chosenRoute.title:'Da definire insieme'}</dd></div><div><dt>Ateneo</dt><dd>Da individuare con il consulente</dd></div></dl><div class=\"request-edit\"><button class=\"text-btn\" data-go=\"result\">${icon('edit')}Rivedi i percorsi</button><button class=\"text-btn\" data-go=\"compare\">Rivedi le tue esigenze</button></div>${complete()?`<details class=\"consultation-context\"><summary>${proposal.consultation.title}</summary><p>${proposal.consultation.text}</p><ul>${proposal.consultation.topics.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:'<p class=\"small\">Non hai ancora scelto un percorso o un ateneo? Puoi partire da un primo orientamento, senza compilare di nuovo il test.</p>'}</section><form class=\"card\" id=\"contact-form\"><div class=\"form-section\"><span class=\"form-step\">01</span><div><h2>Come ti contattiamo?</h2><p class=\"small\">${isLive()?'Scegli il canale preferito. L’email identifica la tua richiesta.':'Un solo canale, un solo recapito.'}</p></div></div><div class=\"channels\" role=\"group\" aria-label=\"Canale di contatto\">${[['WhatsApp','chat'],['Telefonata','phone'],['Email','mail']].map(([c,i])=>`<button type=\"button\" data-channel=\"${c}\" aria-pressed=\"${channel===c}\">${icon(i)}${c}</button>`).join('')}</div><label class=\"field\" for=\"name\">Nome<input id=\"name\" name=\"name\" autocomplete=\"off\" maxlength=\"60\" placeholder=\"Es. Giulia\" value=\"${esc(draft.name)}\" required></label><label class=\"field\" for=\"surname\">Cognome<input id=\"surname\" name=\"surname\" autocomplete=\"family-name\" maxlength=\"60\" value=\"${esc(draft.surname)}\"></label><label class=\"field\" for=\"contact\">${channel==='Email'?'Indirizzo email':'Numero per '+channel.toLowerCase()}<input id=\"contact\" name=\"contact\" autocomplete=\"off\" type=\"${channel==='Email'?'email':'tel'}\" maxlength=\"100\" placeholder=\"${channel==='Email'?'giulia@example.com':'+39 320 000 0000'}\" value=\"${esc(draft.contact)}\" required ${channel!=='Email'?'pattern=\"[+0-9 ()-]{7,25}\"':''} aria-describedby=\"contact-hint\"></label><p class=\"field-hint\" id=\"contact-hint\">${channel==='Email'?'Non serve il numero di telefono.':(isLive()?'Indica anche l’email qui sotto per associare la richiesta. Per numeri esteri, includi il prefisso.':'Non serve l’indirizzo email. Per numeri esteri, indica anche il prefisso internazionale.')}</p>${isLive()&&channel!=='Email'?`<label class=\"field\" for=\"identity-email\">Email per identificare la richiesta<input id=\"identity-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"100\" value=\"${esc(draft.email)}\" required></label>`:''}<div class=\"form-section schedule-heading\"><span class=\"form-step\">02</span><div><h2>Quando preferisci?</h2><p class=\"small\">Indica una preferenza, non una prenotazione.</p></div></div><label class=\"field\" for=\"preferred-day\">Giorno<select id=\"preferred-day\" name=\"day\" class=\"quiz-select\" required><option value=\"\">Scegli una preferenza</option>${[['first','Primo giorno utile'],['date','Una data specifica'],['any','Nessuna preferenza']].map(([v,l])=>`<option value=\"${v}\" ${draft.day===v?'selected':''}>${l}</option>`).join('')}</select></label>${draft.day==='date'?`<label class=\"field\" for=\"preferred-date\">Data preferita<input id=\"preferred-date\" name=\"date\" type=\"date\" min=\"${romeToday()}\" value=\"${esc(draft.date)}\" required></label>`:''}${channel!=='Email'?`<label class=\"field\" for=\"preferred-slot\">Fascia oraria<select id=\"preferred-slot\" name=\"slot\" class=\"quiz-select\" required><option value=\"\">Scegli una fascia</option>${['09:00–12:00','12:00–15:00','15:00–18:00','18:00–20:00','Nessuna preferenza'].map(x=>`<option ${draft.slot===x?'selected':''}>${x}</option>`).join('')}</select></label><p class=\"field-hint\">Orari italiani · Europe/Rome. La fascia scelta non indica disponibilità effettiva.</p>`:'<p class=\"field-hint\">Per l’email non serve una fascia oraria: la leggerai quando preferisci.</p>'}<label class=\"check\"><input id=\"permission\" type=\"checkbox\" required ${draft.permission?'checked':''}><span>${isLive()?'Chiedo di essere ricontattato per una consulenza con queste preferenze. Ho letto l’informativa privacy.':'Confermo di voler provare il ricontatto con queste preferenze.'}</span></label><div class=\"notice form-demo-note\">${icon('shield')}<span>${isLive()?'La richiesta e le preferenze saranno salvate nel CRM Laurea Smart. Una notifica interna avviserà il team di orientamento; nessun messaggio automatico sarà inviato al tuo recapito.':window.LaureaWPCRM?'Collaudo online: il contatto fittizio e le risposte saranno salvati nel CRM Laurea Smart. Nessuna email o WhatsApp automatici.':'Solo una prova: usa dati di fantasia. Nessun dato viene inviato o conservato dopo il ricaricamento.'} Non è un’iscrizione a comunicazioni promozionali. ${isLive()&&window.LaureaWPCRM.privacy?`<a href=\"${esc(window.LaureaWPCRM.privacy)}\" target=\"_blank\" rel=\"noopener\">Informativa privacy</a>`:''}</span></div><p class=\"error\" id=\"form-error\" role=\"alert\"></p><button type=\"submit\" class=\"primary full\">${isLive()?'Richiedi la consulenza':'Conferma la richiesta di prova'}${icon('arrow')}</button></form></div>`;}\nfunction render(){current=Math.min(current,questions().length-1);const hash=location.hash.slice(1);screen=['home','quiz','result','compare','contact','budget','budget-1','budget-2','budget-3','budget-summary','career','career-studies','career-work','career-goal','career-summary'].includes(hash)?hash:'home';document.body.dataset.screen=screen;const views={home,quiz,result:()=>quizAccessRequired()?quizAccessView():result(),compare,contact,...Object.fromEntries(['budget','budget-1','budget-2','budget-3','budget-summary','career','career-studies','career-work','career-goal','career-summary'].map(s=>[s,()=>window.LaureaTools.view(s)]))};document.getElementById('app').innerHTML=`<div class=\"shell\"><header class=\"top\"><button class=\"logo\" data-go=\"home\" aria-label=\"Laurea Smart, torna all’inizio\"><span class=\"logomark\">${icon('cap')}</span><span class=\"wordmark\">LAUREA SMART<span class=\"brand-dot\">.</span></span></button><div class=\"top-right\"><span class=\"demo\">${isLive()?(isTest()?'Collaudo invio':'Orientamento'):window.LaureaWPCRM?'Collaudo CRM':'Prototipo locale'}</span></div></header><main class=\"main\" id=\"main\" tabindex=\"-1\">${views[screen]()}</main></div><nav class=\"nav\" aria-label=\"Navigazione principale\">${[['home','home','Home'],['result','route','Il tuo percorso'],['compare','compass','Preferenze'],['contact','chat','Orientatore']].map(([s,i,l])=>`<button data-go=\"${s}\" class=\"${screen===s||(s==='result'&&(screen==='quiz'||screen.startsWith('budget')||screen.startsWith('career')))?'active':''}\" ${screen===s||(s==='result'&&(screen==='quiz'||screen.startsWith('budget')||screen.startsWith('career')))?'aria-current=\"page\"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav>`;}\nfunction setAnswer(value){const q=questions()[current];if(!q.options.includes(value)||answers[q.id]===value)return;answers[q.id]=value;if(quizAccessEnabled()&&quizAccess.complete)invalidateQuizAccess();answers=Q.sanitize(answers);selectedSchool='';selectedRoute='';submitted=false;save();}\ndocument.addEventListener('change',e=>{if(e.target.id!=='region-answer')return;if(e.target.value===''){delete answers.region;selectedSchool='';selectedRoute='';submitted=false;save();render();document.getElementById('region-answer')?.focus({preventScroll:true});return;}setAnswer(questions()[current].options[Number(e.target.value)]);render();document.getElementById('region-answer')?.focus({preventScroll:true});});\nfunction keepDraft(){const f=document.getElementById('contact-form');if(f){draft.name=f.elements.name.value;if(f.elements.surname)draft.surname=f.elements.surname.value;if(f.elements.email)draft.email=f.elements.email.value;draft.contact=f.elements.contact.value;draft.permission=document.getElementById('permission').checked;draft.day=f.elements.day.value;if(f.elements.date)draft.date=f.elements.date.value;if(f.elements.slot)draft.slot=f.elements.slot.value;}}\ndocument.addEventListener('change',e=>{if(!['preferred-day'].includes(e.target.id))return;keepDraft();render();document.getElementById('preferred-day')?.focus({preventScroll:true});});\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(submitting){e.preventDefault();return;}if(b.dataset.go){keepDraft();go(b.dataset.go);return;}if(b.dataset.answer!==undefined){setAnswer(questions()[current].options[Number(b.dataset.answer)]);const pos=window.scrollY;render();window.scrollTo(0,pos);document.querySelector(`[data-answer=\"${b.dataset.answer}\"]`)?.focus({preventScroll:true});return;}if(b.dataset.route||b.dataset.proposedSchool){const position=window.scrollY;if(b.dataset.route)selectedRoute=b.dataset.route;else selectedSchool=b.dataset.proposedSchool;submitted=false;confirmation=null;render();window.scrollTo(0,position);document.querySelector(b.dataset.route?`[data-route=\"${selectedRoute}\"]`:`[data-proposed-school=\"${selectedSchool}\"]`)?.focus({preventScroll:true});return;}if(b.dataset.school){selectedSchool=b.dataset.school;submitted=false;confirmation=null;const pos=window.scrollY;render();window.scrollTo(0,pos);document.querySelector(`[data-school=\"${selectedSchool}\"]`)?.focus({preventScroll:true});return;}if(b.dataset.channel){keepDraft();const previous=channel;channel=b.dataset.channel;if((previous==='Email')!==(channel==='Email'))draft.contact=channel==='Email'?(draft.email||quizAccess.email):(quizAccess.phone||'');render();document.querySelector(`[data-channel=\"${channel}\"]`)?.focus({preventScroll:true});return;}switch(b.dataset.action){case 'start':current=Math.max(0,questions().findIndex(q=>!answers[q.id]));if(complete()){go('result');}else go('quiz');break;case 'next':if(!answers[questions()[current].id])return;if(current<questions().length-1){current++;render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});}else go('result');break;case 'previous':if(current>0){current--;render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});}else go('home');break;case 'edit':current=0;go('quiz');break;case 'reset':invalidateQuizAccess();quizAccess={step:'email',email:'',name:'',surname:'',phone:'',previousRequestId:'',complete:false,busy:false,error:'',permission:false};answers={};current=0;selectedSchool='';selectedRoute='';submitted=false;draft.email='';draft.name='';draft.surname='';draft.contact='';draft.permission=false;draft.day='';draft.date='';draft.slot='';confirmation=null;try{window.LaureaTools.clear();localStorage.removeItem(STORAGE);localStorage.removeItem('ls-prototype-answers');}catch{}go('home');render();break;case 'new-request':submitted=false;confirmation=null;render();break;}});\ndocument.addEventListener('submit',async e=>{if(e.target.id!=='contact-form')return;e.preventDefault();keepDraft();const fail=text=>{const el=document.getElementById('form-error');if(!el)return;el.textContent=text;el.scrollIntoView({block:'center'});};if(!draft.name.trim()||!draft.contact.trim())return fail('Inserisci un nome e un recapito valido.');if(channel!=='Email'&&(draft.contact.replace(/\\D/g,'').length<7||draft.contact.replace(/\\D/g,'').length>15))return fail('Inserisci un numero da 7 a 15 cifre, con prefisso se necessario.');if(!['first','date','any'].includes(draft.day))return fail('Scegli il giorno in cui preferiresti essere ricontattato.');if(draft.day==='date'&&(!/^\\d{4}-\\d{2}-\\d{2}$/.test(draft.date)||draft.date<romeToday()))return fail('Scegli una data valida, da oggi in poi.');if(channel!=='Email'&&!['09:00–12:00','12:00–15:00','15:00–18:00','18:00–20:00','Nessuna preferenza'].includes(draft.slot))return fail('Scegli una fascia oraria oppure nessuna preferenza.');if(!draft.permission)return fail('Conferma la richiesta di ricontatto.');const route=Q.proposal(answers).routes.find(r=>r.id===selectedRoute);let crm=null;const submitButton=e.target.querySelector('[type=submit]');if(submitting)return;submitting=true;for(const control of e.target.elements)control.disabled=true;submitButton.disabled=true;submitButton.textContent='Verifica della richiesta…';try{crm=await window.LaureaCRM?.send({email:draft.email.trim(),name:draft.name.trim(),surname:draft.surname.trim(),contact:draft.contact.trim(),channel,day:draft.day,date:draft.date,slot:draft.slot,permission:draft.permission,answers,routeId:selectedRoute,schoolId:''});}catch(error){submitting=false;for(const control of e.target.elements)control.disabled=false;if(!e.target.isConnected){go('contact');render();}else{submitButton.disabled=false;submitButton.textContent='Riprova con lo stesso riferimento';}return fail(error.message);}submitting=false;confirmation={crm,route:route?route.title:'Da definire insieme',school:'Da individuare con il consulente',channel,contact:maskedContact(draft.contact.trim()),day:contactWhen(),slot:draft.slot};submitted=true;draft.email='';draft.name='';draft.surname='';draft.contact='';draft.permission=false;if(screen!=='contact')go('contact');render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});});\ndocument.addEventListener('laurea-crm-ready',()=>{if(screen==='contact'&&!submitted){keepDraft();render();}});\nwindow.addEventListener('hashchange',()=>{keepDraft();render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});});render();\n";
const RELEASE_TOOLS_CSS="\n.ls-tools h1{font-size:29px;letter-spacing:-1px;line-height:1.2;margin:0 0 12px;font-weight:800}.ls-tools h2{font-size:20px;letter-spacing:-.6px;margin:0 0 10px}.ls-tools h3{font-size:15px;margin:0 0 8px}.ls-tools p{color:var(--muted);font-size:14px;line-height:1.7;margin:0 0 18px}.ls-tools .eyebrow{font-size:10px;letter-spacing:1.4px;text-transform:uppercase;color:var(--blue);font-weight:800;margin-bottom:12px}.ls-tools .card{border:1px solid var(--line);border-radius:15px;padding:22px;margin:18px 0;background:white}.ls-tools .card.soft{background:#f8f9fc}.ls-tools .card-link{display:block;color:inherit;text-decoration:none}.ls-tools .card-link:hover{border-color:var(--blue)}.ls-tools .row{display:flex;justify-content:space-between;align-items:center;gap:14px}.ls-tools .tag{display:inline-block;color:var(--blue);background:#edf1fa;padding:5px 9px;border-radius:5px;font-size:10px;font-weight:750;margin:12px 0}.ls-tools .arrow{font-size:24px;color:var(--blue)}.ls-tools .icon{font-size:22px;color:var(--blue);margin-bottom:17px}.ls-tools .primary,.ls-tools .secondary{width:100%;min-height:50px;border-radius:9px;padding:13px 16px;font-size:13px;font-weight:750;display:flex;align-items:center;justify-content:center;text-align:center;text-decoration:none;margin-top:12px}.ls-tools .primary{background:var(--blue);color:white;border:1px solid var(--blue)}.ls-tools .secondary{background:white;color:var(--blue);border:1px solid #cfd8e8}.ls-tools .text{min-height:44px;border:0;background:none;padding:10px 0;color:var(--blue);font-weight:700;font-size:12px;text-decoration:none;display:inline-flex;align-items:center}.ls-tools .small{font-size:11px;line-height:1.65;color:var(--muted)}.ls-tools .notice{border-left:3px solid #a6b4d5;padding:10px 13px;font-size:12px;color:var(--muted);background:#f8f9fc;line-height:1.6;margin:20px 0}.ls-tools .progress{display:flex;gap:6px;margin:12px 0 24px}.ls-tools .progress i{height:3px;border-radius:2px;flex:1;background:#e7ebf1}.ls-tools .progress i.on{background:var(--blue)}.ls-tools .step{font-size:11px;color:var(--muted)}.ls-tools fieldset{border:0;padding:0;margin:22px 0}.ls-tools legend,.ls-tools label.title{display:block;font-size:14px;font-weight:750;margin:0 0 12px}.ls-tools .options{display:grid;gap:10px}.ls-tools .option{display:flex;align-items:center;gap:12px;min-height:56px;border:1px solid var(--line);border-radius:10px;padding:14px;font-size:13px;cursor:pointer}.ls-tools .option:has(input:checked){background:#f1f4fb;border-color:var(--blue);color:#293f79}.ls-tools .option input{width:18px;height:18px;accent-color:var(--blue);margin:0;flex-shrink:0}.ls-tools .option span{flex:1}.ls-tools .option small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.ls-tools .field{margin:20px 0}.ls-tools .field label{display:block;font-size:13px;font-weight:750;margin:0 0 9px}.ls-tools input[type=text],.ls-tools input[type=number],.ls-tools textarea{width:100%;min-height:50px;border:1px solid #cfd7e3;border-radius:9px;padding:12px;background:white;font-size:16px;color:#202938}.ls-tools textarea{min-height:100px;resize:vertical}.ls-tools .error{color:#a52c3a;font-size:12px;margin:10px 0}.ls-tools .facts{margin:12px 0}.ls-tools .facts div{padding:15px 0;border-bottom:1px solid var(--line)}.ls-tools dt{font-size:11px;color:var(--muted);margin-bottom:6px}.ls-tools dd{font-size:14px;font-weight:700;margin:0;line-height:1.65;overflow-wrap:anywhere}.ls-tools .linkrow{display:flex;justify-content:space-between;gap:12px;align-items:center}.ls-tools .money{font-size:34px;font-weight:800;letter-spacing:-1.4px;margin:8px 0}.ls-tools .money small{font-size:13px;color:var(--muted);letter-spacing:0;font-weight:500}.ls-tools .split{display:grid;grid-template-columns:1fr 1fr;gap:12px}.ls-tools .split .field{margin:12px 0}.ls-tools .footer-note{padding-top:20px;margin-top:24px;border-top:1px solid var(--line)}\n.ls-tools-entry{margin:26px 0}.ls-tools-entry>.small{margin-top:12px}.ls-tools .primary{display:flex}.ls-tools .error{color:#a52c3a}.ls-tools details summary{cursor:pointer;min-height:44px;font-weight:700}.ls-tools-entry .line-icon{font-size:22px}\n";

export async function middleware(request) {
  const url = new URL(request.url);
  const path = url.pathname;
  const isPost = path === '/ls-request';
  const isAsset = path.startsWith('/ls-assets/');
  const isPWA = path === '/manifest.webmanifest' || path === '/sw.js';
  const headers = new Headers({ 'Cache-Control': 'private, no-store', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'same-origin', 'X-Laurea-Release': 'web-20261101-budget-carriera' });
  const fail = (message, status) => new Response(JSON.stringify({ ok: false, message }), { status, headers: { ...Object.fromEntries(headers), 'Content-Type': 'application/json' } });
  if (isPost ? request.method !== 'POST' : !['GET', 'HEAD'].includes(request.method)) return fail('Metodo non consentito.', 405);
  const upstreamHeaders = new Headers();
  let body;
  if (isPost) {
    // Validate the browser origin here before using the existing site's origin guard.
    if (request.headers.get('origin') !== APP_ORIGIN || url.origin !== APP_ORIGIN) return fail('Inviare la richiesta dall’app Laurea Smart.', 403);
    if (!request.headers.get('content-type')?.startsWith('application/json')) return fail('Formato non valido.', 415);
    if (Number(request.headers.get('content-length')) > 32768) return fail('Richiesta troppo grande.', 413);
    body = await request.text();
    if (new TextEncoder().encode(body).length > 32768) return fail('Richiesta troppo grande.', 413);
    upstreamHeaders.set('Content-Type', 'application/json');
    upstreamHeaders.set('Origin', SITE);
    upstreamHeaders.set('X-Laurea-Session', request.headers.get('x-laurea-session') || '');
    const session = (request.headers.get('cookie') || '').split(';').map(v => v.trim()).find(v => v.startsWith('__Host-ls_app_session='));
    if (!session) return fail('Sessione dell’app non disponibile. Ricarica il modulo e riprova.', 403);
    const sessionValue = session.slice('__Host-ls_app_session='.length);
    if (sessionValue !== request.headers.get('x-laurea-session')) return fail('Sessione dell’app non aggiornata. Ricarica il modulo e riprova.', 403);
    upstreamHeaders.set('Cookie', 'ls_form_session=' + sessionValue);
  }
  let target = SITE + '/wp-admin/admin-post.php?action=' + (path === '/privacy' ? 'laureasmart_privacy' : 'laureasmart_app');
  if (isPost) target = SITE + '/wp-json/laureasmart/v1/request';
  if (isPWA) target = SITE + ASSETS + (path === '/sw.js' ? 'pwa-worker.js' : 'manifest.webmanifest');
  if (isAsset) {
    const name = path.slice('/ls-assets/'.length);
    if (!/^(?:styles\.css|qualification\.js|crm-client\.js|quiz-access\.js|app\.js|pwa\.js|icons\/icon-(?:192|512)\.png|brand-kit\/fonts\/manrope-variable\.ttf)$/.test(name)) return fail('Risorsa non trovata.', 404);
    target = SITE + ASSETS + name + url.search;
  }
  if(isAsset && path==='/ls-assets/app.js'){headers.set('Content-Type','application/javascript; charset=utf-8');return new Response(request.method==='HEAD'?null:RELEASE_APP_JS,{headers});}
  try {
    const upstream = await fetch(target, { method: isPost ? 'POST' : 'GET', headers: upstreamHeaders, body, redirect: 'error', cache: 'no-store', signal: AbortSignal.timeout(55000) });
    const type = upstream.headers.get('content-type') || 'application/octet-stream';
    headers.set('Content-Type', type);
    if (isPWA) { headers.set('Cache-Control', 'public, max-age=0, must-revalidate'); headers.set('Content-Type', path === '/sw.js' ? 'application/javascript; charset=utf-8' : 'application/manifest+json; charset=utf-8'); if (path === '/sw.js') headers.set('Service-Worker-Allowed', '/'); }
    if(isAsset && path==='/ls-assets/styles.css' && upstream.ok){return new Response(request.method==='HEAD'?null:(await upstream.text())+RELEASE_TOOLS_CSS,{status:upstream.status,headers});}
    if (isPost || isAsset || isPWA || !type.includes('text/html')) return new Response(request.method === 'HEAD' ? null : upstream.body, { status: upstream.status, headers });
    let html = await upstream.text();
    html = html.replace(/window\.LaureaWPCRM=(\{.*?\});<\/script>/, (_, json) => {
      const config = JSON.parse(json);
      // Bind the WordPress-signed token to an HttpOnly cookie on the actual app host.
      // Never reconstruct this cookie from a submitted header or expose credentials.
      if (!/^[a-f0-9]{32}\.\d+\.live\.[a-f0-9]{64}$/.test(config.token)) throw new Error('Invalid session');
      headers.set('Set-Cookie', '__Host-ls_app_session=' + config.token + '; Path=/; Max-Age=7200; Secure; HttpOnly; SameSite=Strict');
      config.api = '/ls-request';
      config.privacy = '/privacy';
      return 'window.LaureaWPCRM=' + JSON.stringify(config).replace(/</g, '\\u003c') + ';</script>';
    });
    html = html.split(SITE + ASSETS).join('/ls-assets/');
    if (path !== '/privacy') html = html.replace('</head>', '<link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#ffffff"><link rel="icon" type="image/png" href="/ls-assets/icons/icon-192.png"><link rel="apple-touch-icon" href="/ls-assets/icons/icon-192.png"></head>');
    if (path === '/privacy' && !html.includes('sono gestiti tramite Vercel')) {
      html = html.replace('percorso e modello di ateneo eventualmente scelti', 'percorso eventualmente scelto e preferenze per individuare l’ateneo');
      html = html.replace('</body>', '<p>L’interfaccia su app.laureasmart.it è distribuita tramite Vercel, che gestisce anche il transito tecnico della richiesta verso il sito WordPress. La richiesta viene poi gestita nel CRM Laurea Smart come descritto sopra. Per informazioni sui fornitori, sulle ubicazioni del trattamento e sulle garanzie applicabili puoi contattare info@laureasmart.it.</p></body>');
    }
    return new Response(request.method === 'HEAD' ? null : html, { status: upstream.status, headers });
  } catch {
    return new Response('<!doctype html><html lang="it"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laurea Smart</title><body style="font-family:system-ui;padding:32px"><h1>LAUREA SMART</h1><p>Connessione momentaneamente non disponibile. Riprova tra poco.</p><a href="/">Riprova</a></body></html>', { status: 503, headers: { ...Object.fromEntries(headers), 'Content-Type': 'text/html; charset=utf-8' } });
  }
}

export const config = { matcher: ['/', '/privacy', '/ls-request', '/ls-assets/:path*', '/manifest.webmanifest', '/sw.js'] };
